namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Exploration of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Literature, composition, rhetoric, and creative writing." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events, societies, and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "Foundational concepts in computing including problem solving, abstraction, and Python programming. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace specializes in programming languages and computer science education with 15 years of teaching experience.", IsFeatured = true, DepartmentCode = "CS", DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Arrays, linked lists, trees, graphs, sorting, and algorithmic complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing is a leading researcher in algorithm design and computational complexity theory.", IsFeatured = false, DepartmentCode = "CS", DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, Code = "CS 310", Title = "Database Systems", Description = "Relational databases, SQL, normalization, transaction processing, and an introduction to NoSQL.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Edgar Codd", InstructorBio = "Dr. Codd has published extensively on relational models and data management.", IsFeatured = false, DepartmentCode = "CS", DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 1, Code = "CS 420", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, and practical applications using Python.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace specializes in programming languages and computer science education with 15 years of teaching experience.", IsFeatured = true, DepartmentCode = "CS", DepartmentName = "Computer Science" },
            new() { Id = 5, DepartmentId = 2, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an award-winning mathematician recognized for excellence in undergraduate teaching.", IsFeatured = true, DepartmentCode = "MATH", DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 2, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an award-winning mathematician recognized for excellence in undergraduate teaching.", IsFeatured = false, DepartmentCode = "MATH", DepartmentName = "Mathematics" },
            new() { Id = 7, DepartmentId = 2, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability distributions, hypothesis testing, regression analysis, and Bayesian methods.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", InstructorName = "Dr. Carl Gauss", InstructorBio = "Dr. Gauss brings 20 years of industry experience in statistical modeling and data science.", IsFeatured = false, DepartmentCode = "MATH", DepartmentName = "Mathematics" },
            new() { Id = 8, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves with calculus-based problem solving and laboratory work.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is known for making complex physics accessible and engaging for undergraduates.", IsFeatured = true, DepartmentCode = "PHYS", DepartmentName = "Physics" },
            new() { Id = 9, DepartmentId = 3, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is known for making complex physics accessible and engaging for undergraduates.", IsFeatured = false, DepartmentCode = "PHYS", DepartmentName = "Physics" },
            new() { Id = 10, DepartmentId = 4, Code = "ENG 101", Title = "College Composition", Description = "Develop critical thinking and academic writing skills through essays, research papers, and peer review.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Maya Angelou", InstructorBio = "Dr. Angelou is a published author and specialist in rhetoric and composition studies.", IsFeatured = false, DepartmentCode = "ENG", DepartmentName = "English" },
            new() { Id = 11, DepartmentId = 4, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present day.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. Maya Angelou", InstructorBio = "Dr. Angelou is a published author and specialist in rhetoric and composition studies.", IsFeatured = false, DepartmentCode = "ENG", DepartmentName = "English" },
            new() { Id = 12, DepartmentId = 5, Code = "HIST 101", Title = "World History to 1500", Description = "Major civilizations, cultures, and events from antiquity through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Howard Zinn", InstructorBio = "Dr. Zinn is a historian specializing in social movements and comparative world history.", IsFeatured = false, DepartmentCode = "HIST", DepartmentName = "History" },
            new() { Id = 13, DepartmentId = 5, Code = "HIST 202", Title = "Modern European History", Description = "Europe from the Enlightenment through the 21st century: revolutions, wars, and cultural transformations.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", InstructorName = "Dr. Howard Zinn", InstructorBio = "Dr. Zinn is a historian specializing in social movements and comparative world history.", IsFeatured = false, DepartmentCode = "HIST", DepartmentName = "History" },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetAllCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

